public class DownloadProgressPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    static int barValue(java.awt.Component c) {
        if (c instanceof javax.swing.JProgressBar) {
            return ((javax.swing.JProgressBar) c).getValue();
        }
        return -1;
    }

    public static void main(String[] args) {
        try {
            DownloadProgressPanel panel = new DownloadProgressPanel();
            java.awt.Component barComp = find(panel, "bar");
            java.awt.Component statusComp = find(panel, "status");
            check("progress bar found", true, barComp instanceof javax.swing.JProgressBar);
            check("startup status text", "0% of 200", labelText(statusComp));
            panel.setDownloaded(50);
            check("quarter done bar value", 25, barValue(barComp));
            check("quarter done status", "25% of 200", labelText(statusComp));
            panel.setDownloaded(1);
            check("one unit rounds up to 1 percent", 1, panel.getPercent());
            panel.setDownloaded(999);
            check("over-large value clamps to 100", "100% of 200", labelText(statusComp));
            panel.setDownloaded(-40);
            check("negative value clamps to 0", 0, barValue(barComp));
            check("negative value clamps getPercent too", 0, panel.getPercent());
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
