import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JProgressBar;

public class DownloadProgressPanel extends JPanel {

    public static final int TOTAL_UNITS = 200;

    private final JProgressBar bar = new JProgressBar(0, 100);
    private final JLabel status = new JLabel("(idle)");
    private int done = 0;

    public DownloadProgressPanel() {
        bar.setName("bar");
        status.setName("status");
        add(bar);
        add(status);
        refresh();
    }

    /** Provided: the stored progress as a whole percentage. */
    public int getPercent() {
        return (int) Math.round(done * 100.0 / TOTAL_UNITS);
    }

    public void setDownloaded(int units) {
        if (units < 0) {
            done = 0;
        } else if (units > TOTAL_UNITS) {
            done = TOTAL_UNITS;
        } else {
            done = units;
        }
        refresh();
    }

    public void refresh() {
        bar.setValue(getPercent());
        status.setText(getPercent() + "% of " + TOTAL_UNITS);
    }
}
